  5→import { apiClient, type ApiResult } from '@/lib/api-client';
  6→import type {
  7→  DashboardMetricsResponse,
  8→  PaymentDynamicsResponse,
  9→  PaymentDynamicsQueryParams,
 10→  UploadBankStatementResponse,
 11→} from '@/types/fastapi';
 12→
 13→const BASE_PATH = '/api/analytics';
 14→
 15→// =============================================================================
 16→// Dashboard Metrics
 17→// =============================================================================
 18→
 19→/**
 20→ * Get dashboard metrics for financial visibility
 21→ * @param params - Optional date range filters (period_start, period_end)
 22→ */
 23→export async function getDashboardMetrics(
 24→  params?: { period_start?: string; period_end?: string }
 25→): Promise<ApiResult<DashboardMetricsResponse>> {
 26→  return apiClient.get<DashboardMetricsResponse>(`${BASE_PATH}/dashboard`, params);
 27→}
 28→
 29→// =============================================================================
 30→// Payment Dynamics
 31→// =============================================================================
 32→
 33→/**
 34→ * Get payment dynamics time-series data for charts
 35→ * @param params - Date range and grouping options
 36→ */
 37→export async function getPaymentDynamics(
 38→  params?: PaymentDynamicsQueryParams
 39→): Promise<ApiResult<PaymentDynamicsResponse>> {
 40→  return apiClient.get<PaymentDynamicsResponse>(`${BASE_PATH}/payment-dynamics`, params);
 41→}
 42→
 43→// =============================================================================
 44→// Export
 45→// =============================================================================
 46→
 47→/**
 48→ * Export transactions to Excel file
 49→ * @param params - Date filters and limit
 50→ * @returns Blob with Excel file content
 51→ */
 52→export async function exportTransactionsExcel(
 53→  params?: {
 54→    date_from?: string;
 55→    date_to?: string;
 56→    limit?: number;
 57→  }
 58→): Promise<Blob> {
 59→  const url = `${BASE_PATH}/export/transactions`;
 60→  const queryString = params
 61→    ? '?' + new URLSearchParams(
 62→        Object.entries(params).filter(([_, v]) => v !== undefined) as [string, string][]
 63→      ).toString()
 64→    : '';
 65→
 66→  const response = await fetch(url + queryString);
 67→  if (!response.ok) {
 68→    throw new Error(`Export failed: ${response.statusText}`);
 69→  }
 70→  return response.blob();
 71→}
 72→
 73→// =============================================================================
 74→// Bank Statement Upload
 75→// =============================================================================
 76→
 77→/**
 78→ * Upload a bank statement file for manual reconciliation
 79→ * @param file - Bank statement file (1C ClientBank .txt format)
 80→ */
 81→export async function uploadBankStatement(
 82→  file: File
 83→): Promise<ApiResult<UploadBankStatementResponse>> {
 84→  const formData = new FormData();
 85→  formData.append('file', file);
 86→
 87→  const FASTAPI_URL = process.env.FASTAPI_URL || 'http://localhost:8000';
 88→  const FASTAPI_AUTH_TOKEN = process.env.FASTAPI_AUTH_TOKEN;
 89→
 90→  const headers: Record<string, string> = {};
 91→  if (FASTAPI_AUTH_TOKEN) {
 92→    headers['Authorization'] = `Bearer ${FASTAPI_AUTH_TOKEN}`;
 93→  }
 94→
 95→  try {
 96→    const response = await fetch(`${FASTAPI_URL}${BASE_PATH}/upload-bank-statement`, {
 97→      method: 'POST',
 98→      headers,
 99→      body: formData,
100→    });
101→
102→    const body = await response.json();
103→
104→    if (!response.ok) {
105→      return {
106→        data: null,
107→        error: {
108→          error: body.detail || 'Upload failed',
109→          details: body,
110→        },
111→      };
112→    }
113→
114→    return { data: body, error: null };
115→  } catch (err) {
116→    return {
117→      data: null,
118→      error: {
119→        error: err instanceof Error ? err.message : 'Network error',
120→      },
121→    };
122→  }
123→}
124→
125→// =============================================================================
